parameters.jsCode:
// Consolidar información del Webhook original con la decisión del AI Agent
const rawInput = $input.first().json;
let aiOutput = rawInput.output || rawInput;

if (typeof aiOutput === 'string') {
  try {
    aiOutput = JSON.parse(aiOutput);
  } catch (e) {
    const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        aiOutput = JSON.parse(jsonMatch[0]);
      } catch (err) {
        aiOutput = { respuesta_oficial: aiOutput };
      }
    } else {
      aiOutput = { respuesta_oficial: aiOutput };
    }
  }
}

// Obtener datos originales del webhook
const webhookData = $('Webhook Trigger PQRS').first().json.body || $('Webhook Trigger PQRS').first().json;

const randomTicketNum = Math.floor(1000 + Math.random() * 9000);
const currentYear = new Date().getFullYear();
const ticketId = `PQ-${currentYear}-${randomTicketNum}`;
const fechaActual = new Date().toISOString().split('T')[0];
const horaActual = new Date().toLocaleTimeString('es-CR');

// Departamento y prioridad decididos por el AI Agent (soporta camelCase y snake_case)
const departamento = aiOutput.departamento || aiOutput.department || (webhookData.categoria === 'Aduanas' ? 'Unidad de Aforo Fiscal y Postal' : 'Soporte y Atención Ciudadana');
const prioridad = aiOutput.prioridadCalculada || aiOutput.urgencia || aiOutput.prioridad || webhookData.prioridad || 'Media';
const sla = aiOutput.slaHoras || aiOutput.sla || (prioridad === 'Alta' ? '24 horas hábiles' : '48 horas hábiles');
const resumen = aiOutput.resumenEjecutivo || aiOutput.resumen_ejecutivo || aiOutput.resumen || webhookData.asunto || 'Gestión ciudadana';
const respuestaCiudadano = aiOutput.respuestaAlCiudadano || aiOutput.respuesta_oficial || aiOutput.respuestaOficial || aiOutput.respuesta || aiOutput.response || aiOutput.output || aiOutput.text || `Estimado(a) ciudadano(a), su gestión ha sido radicada bajo el código ${ticketId}.`;
const sentimiento = aiOutput.analisisSentimiento || aiOutput.sentimiento || 'Neutral/Informativo';

const ticketCompleto = {
  ticket: ticketId,
  usuario: webhookData.usuario || 'Ciudadano Registrado',
  correo: webhookData.correo || '',
  categoria: webhookData.categoria || 'General',
  prioridad: prioridad,
  prioridadOriginal: webhookData.prioridad || 'Media',
  asunto: webhookData.asunto || 'Consulta sin asunto',
  mensaje: webhookData.mensaje || '',
  estado: 'En Investigación',
  fecha: fechaActual,
  hora: horaActual,
  n8nProcessed: true,
  aiAgentProcessed: true,
  aiModel: 'DeepSeek / AI Agent (LangChain)',
  n8nDepartment: departamento,
  slaHoras: sla,
  resumenEjecutivo: resumen,
  respuestaAlCiudadano: respuestaCiudadano,
  analisisSentimiento: sentimiento,
  accionesRecomendadas: aiOutput.accionesRecomendadas || aiOutput.acciones_recomendadas || ['Asignar a analista de turno']
};

return [{
  json: ticketCompleto
}];
